CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address every withdrawal confirmation goes to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Optional public name used on referral links. Trading itself is never attributed publicly.
	"handle" VARCHAR(30) UNIQUE,
	-- ISO 3166-1 alpha-2 residence. Decides which markets and leverage are offered, which is a legal question before it is a product one.
	"country_code" CHAR(2) NOT NULL,
	-- Tiered verification, 0 to 3. Each level raises withdrawal limits; level 0 can deposit and trade but never withdraw.
	"kyc_level" SMALLINT NOT NULL DEFAULT 0,
	-- Current fee tier, recalculated from rolling volume. Null falls back to the base tier, which keeps new accounts working before the first volume job runs.
	"fee_tier_id" BIGINT,
	-- active | restricted | frozen | closed. Frozen blocks withdrawals and new orders but leaves existing orders cancellable.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Whether a second factor is required for withdrawals. Tracked here because policy on withdrawal size depends on it.
	"two_factor_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An account holder. Everything an exchange owes to a person hangs off this row, which is why it is soft-statused rather than deletable: a closed account can still have an unconfirmed on-chain deposit arriving.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address every withdrawal confirmation goes to.';
COMMENT ON COLUMN "users"."handle" IS 'Optional public name used on referral links. Trading itself is never attributed publicly.';
COMMENT ON COLUMN "users"."country_code" IS 'ISO 3166-1 alpha-2 residence. Decides which markets and leverage are offered, which is a legal question before it is a product one.';
COMMENT ON COLUMN "users"."kyc_level" IS 'Tiered verification, 0 to 3. Each level raises withdrawal limits; level 0 can deposit and trade but never withdraw.';
COMMENT ON COLUMN "users"."fee_tier_id" IS 'Current fee tier, recalculated from rolling volume. Null falls back to the base tier, which keeps new accounts working before the first volume job runs.';
COMMENT ON COLUMN "users"."status" IS 'active | restricted | frozen | closed. Frozen blocks withdrawals and new orders but leaves existing orders cancellable.';
COMMENT ON COLUMN "users"."two_factor_enabled" IS 'Whether a second factor is required for withdrawals. Tracked here because policy on withdrawal size depends on it.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "assets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticker such as BTC or USD. Unique inside the exchange, which is a listing decision rather than a fact about the world.
	"symbol" VARCHAR(16) NOT NULL UNIQUE,
	-- Full name shown in the asset picker.
	"name" VARCHAR(120) NOT NULL,
	-- crypto | fiat | stablecoin. Fiat balances move over banking rails and never have a transaction hash.
	"asset_class" VARCHAR(12) NOT NULL,
	-- Number of decimal places in the smallest unit: 8 for BTC, 18 for ETH, 2 for USD. Every amount column in this schema is an integer count of that smallest unit, and this column is the scale needed to display it.
	"decimals" SMALLINT NOT NULL,
	-- Settlement network, such as bitcoin or ethereum. Null for fiat. The same token on two chains is two rows, because an address on one is worthless on the other.
	"chain" VARCHAR(32),
	-- Token contract for chain-native tokens. Null for coins and fiat.
	"contract_address" VARCHAR(128),
	-- Block confirmations before a deposit is credited. Set per asset because reorg risk differs wildly between chains.
	"confirmations_required" SMALLINT NOT NULL DEFAULT 6,
	-- Smallest withdrawal allowed, in smallest units, usually set so the network fee does not exceed the amount.
	"min_withdrawal_base" NUMERIC(78,0),
	-- Cut during chain upgrades and incidents without delisting the asset.
	"deposits_enabled" BOOLEAN NOT NULL DEFAULT true,
	-- Toggled independently of deposits, because the usual incident response is to stop money leaving first.
	"withdrawals_enabled" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "assets" IS 'A currency the exchange holds. Balances, deposits and withdrawals all key on it; markets are built from pairs of these rows rather than from symbol strings.';
COMMENT ON COLUMN "assets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "assets"."symbol" IS 'Ticker such as BTC or USD. Unique inside the exchange, which is a listing decision rather than a fact about the world.';
COMMENT ON COLUMN "assets"."name" IS 'Full name shown in the asset picker.';
COMMENT ON COLUMN "assets"."asset_class" IS 'crypto | fiat | stablecoin. Fiat balances move over banking rails and never have a transaction hash.';
COMMENT ON COLUMN "assets"."decimals" IS 'Number of decimal places in the smallest unit: 8 for BTC, 18 for ETH, 2 for USD. Every amount column in this schema is an integer count of that smallest unit, and this column is the scale needed to display it.';
COMMENT ON COLUMN "assets"."chain" IS 'Settlement network, such as bitcoin or ethereum. Null for fiat. The same token on two chains is two rows, because an address on one is worthless on the other.';
COMMENT ON COLUMN "assets"."contract_address" IS 'Token contract for chain-native tokens. Null for coins and fiat.';
COMMENT ON COLUMN "assets"."confirmations_required" IS 'Block confirmations before a deposit is credited. Set per asset because reorg risk differs wildly between chains.';
COMMENT ON COLUMN "assets"."min_withdrawal_base" IS 'Smallest withdrawal allowed, in smallest units, usually set so the network fee does not exceed the amount.';
COMMENT ON COLUMN "assets"."deposits_enabled" IS 'Cut during chain upgrades and incidents without delisting the asset.';
COMMENT ON COLUMN "assets"."withdrawals_enabled" IS 'Toggled independently of deposits, because the usual incident response is to stop money leaving first.';

CREATE TABLE IF NOT EXISTS "markets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pair symbol such as BTC-USD, used in the public API. Derived from the two assets but stored so it stays stable if a display name changes.
	"symbol" VARCHAR(24) NOT NULL UNIQUE,
	-- Asset being bought or sold. Quantity is always expressed in this asset.
	"base_asset_id" BIGINT NOT NULL,
	-- Asset the price is denominated in. Price is always quote per base, which is the one convention that stops sign errors everywhere else.
	"quote_asset_id" BIGINT NOT NULL,
	-- active | post_only | cancel_only | halted | delisted. post_only and cancel_only are the graceful degradations used during incidents.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Smallest order the book accepts, in base smallest units. Stops dust orders from filling the book.
	"min_order_base" NUMERIC(78,0) NOT NULL,
	-- Quantity increment. An order whose size is not a multiple is rejected rather than rounded, because rounding someone order size silently is indefensible.
	"step_size_base" NUMERIC(78,0) NOT NULL,
	-- Price increment in quote smallest units. Coarser ticks mean fewer price levels and a denser, faster book.
	"tick_size_quote" NUMERIC(78,0) NOT NULL,
	-- When trading opened.
	"listed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When trading closed permanently. The row stays so historical trades still resolve.
	"delisted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "markets" IS 'One order book. Keeping base and quote as foreign keys rather than parsing a symbol string is what lets a single query answer which books a halted asset appears in.';
COMMENT ON COLUMN "markets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "markets"."symbol" IS 'Pair symbol such as BTC-USD, used in the public API. Derived from the two assets but stored so it stays stable if a display name changes.';
COMMENT ON COLUMN "markets"."base_asset_id" IS 'Asset being bought or sold. Quantity is always expressed in this asset.';
COMMENT ON COLUMN "markets"."quote_asset_id" IS 'Asset the price is denominated in. Price is always quote per base, which is the one convention that stops sign errors everywhere else.';
COMMENT ON COLUMN "markets"."status" IS 'active | post_only | cancel_only | halted | delisted. post_only and cancel_only are the graceful degradations used during incidents.';
COMMENT ON COLUMN "markets"."min_order_base" IS 'Smallest order the book accepts, in base smallest units. Stops dust orders from filling the book.';
COMMENT ON COLUMN "markets"."step_size_base" IS 'Quantity increment. An order whose size is not a multiple is rejected rather than rounded, because rounding someone order size silently is indefensible.';
COMMENT ON COLUMN "markets"."tick_size_quote" IS 'Price increment in quote smallest units. Coarser ticks mean fewer price levels and a denser, faster book.';
COMMENT ON COLUMN "markets"."listed_at" IS 'When trading opened.';
COMMENT ON COLUMN "markets"."delisted_at" IS 'When trading closed permanently. The row stays so historical trades still resolve.';

CREATE UNIQUE INDEX "uq_markets_base_quote"
ON "markets" ("base_asset_id", "quote_asset_id");

CREATE TABLE IF NOT EXISTS "wallet_balances" (
	-- Balance owner. Half of the composite primary key.
	"user_id" BIGINT,
	-- Asset held. One row per user per asset, created lazily on first credit.
	"asset_id" BIGINT,
	-- Spendable balance as an integer count of smallest units. This is the only number an order or withdrawal may draw down, and it may never go negative.
	"available_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- Funds committed to open orders and pending withdrawals. Visible to the user, untouchable by any new commitment. Total holdings are available plus locked.
	"locked_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- Last movement, used to spot stale rows during reconciliation against the chain.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id", "asset_id")
);

COMMENT ON TABLE "wallet_balances" IS 'The single row every money movement contends on. Splitting available from locked is the entire concurrency design: placing an order moves value from one column to the other inside one transaction, so two orders can never both spend the same coin.';
COMMENT ON COLUMN "wallet_balances"."user_id" IS 'Balance owner. Half of the composite primary key.';
COMMENT ON COLUMN "wallet_balances"."asset_id" IS 'Asset held. One row per user per asset, created lazily on first credit.';
COMMENT ON COLUMN "wallet_balances"."available_base" IS 'Spendable balance as an integer count of smallest units. This is the only number an order or withdrawal may draw down, and it may never go negative.';
COMMENT ON COLUMN "wallet_balances"."locked_base" IS 'Funds committed to open orders and pending withdrawals. Visible to the user, untouchable by any new commitment. Total holdings are available plus locked.';
COMMENT ON COLUMN "wallet_balances"."updated_at" IS 'Last movement, used to spot stale rows during reconciliation against the chain.';

CREATE INDEX "idx_balances_asset"
ON "wallet_balances" ("asset_id");

CREATE TABLE IF NOT EXISTS "balance_locks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the locked funds.
	"user_id" BIGINT NOT NULL,
	-- Asset locked. For a buy order this is the quote asset, for a sell the base asset.
	"asset_id" BIGINT NOT NULL,
	-- order | withdrawal | compliance. A compliance lock is placed by a human and released by one.
	"lock_type" VARCHAR(16) NOT NULL,
	-- Order that caused the lock. Exactly one of order_id and withdrawal_id is set for automatic locks; both are null for a compliance hold.
	"order_id" BIGINT,
	-- Withdrawal that caused the lock.
	"withdrawal_id" BIGINT,
	-- Amount originally locked, in smallest units. For a buy this is quantity times price plus the worst-case taker fee, so a fill can never leave the account short.
	"amount_base" NUMERIC(78,0) NOT NULL,
	-- How much has been released back or consumed by fills. The outstanding hold is amount minus released, and the sum of outstanding holds per asset must equal locked_base exactly.
	"released_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- held | partially_released | released. A partial fill releases the consumed part and leaves the rest held for the unfilled remainder.
	"status" VARCHAR(20) NOT NULL DEFAULT 'held',
	-- When the hold was placed.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the last of it was released.
	"released_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "balance_locks" IS 'The audit trail behind locked_base. The aggregate column on wallet_balances is what queries read, and this table is what proves it right: any drift between the sum here and the column there is a bug that would otherwise be invisible.';
COMMENT ON COLUMN "balance_locks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "balance_locks"."user_id" IS 'Owner of the locked funds.';
COMMENT ON COLUMN "balance_locks"."asset_id" IS 'Asset locked. For a buy order this is the quote asset, for a sell the base asset.';
COMMENT ON COLUMN "balance_locks"."lock_type" IS 'order | withdrawal | compliance. A compliance lock is placed by a human and released by one.';
COMMENT ON COLUMN "balance_locks"."order_id" IS 'Order that caused the lock. Exactly one of order_id and withdrawal_id is set for automatic locks; both are null for a compliance hold.';
COMMENT ON COLUMN "balance_locks"."withdrawal_id" IS 'Withdrawal that caused the lock.';
COMMENT ON COLUMN "balance_locks"."amount_base" IS 'Amount originally locked, in smallest units. For a buy this is quantity times price plus the worst-case taker fee, so a fill can never leave the account short.';
COMMENT ON COLUMN "balance_locks"."released_base" IS 'How much has been released back or consumed by fills. The outstanding hold is amount minus released, and the sum of outstanding holds per asset must equal locked_base exactly.';
COMMENT ON COLUMN "balance_locks"."status" IS 'held | partially_released | released. A partial fill releases the consumed part and leaves the rest held for the unfilled remainder.';
COMMENT ON COLUMN "balance_locks"."created_at" IS 'When the hold was placed.';
COMMENT ON COLUMN "balance_locks"."released_at" IS 'When the last of it was released.';

CREATE INDEX "idx_locks_user_asset_status"
ON "balance_locks" ("user_id", "asset_id", "status");
CREATE INDEX "idx_locks_order"
ON "balance_locks" ("order_id");

CREATE TABLE IF NOT EXISTS "fee_tiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ordinal from 0 upwards. Ordering matters, so this is a number and not a name.
	"tier_level" SMALLINT NOT NULL UNIQUE,
	-- Display name shown on the fee page.
	"name" VARCHAR(40) NOT NULL,
	-- Rolling thirty-day volume threshold in quote smallest units, normalised to a reference currency. Entering the tier is automatic once volume crosses it.
	"min_30d_volume_quote" NUMERIC(78,0) NOT NULL,
	-- Maker fee in basis points. Integer, because a rate stored as a float turns into a fee that does not match the published table. Can be negative: paying makers to post liquidity is a normal strategy.
	"maker_fee_bps" INTEGER NOT NULL,
	-- Taker fee in basis points, always above the maker fee. The spread between the two is what pays for the book being there at all.
	"taker_fee_bps" INTEGER NOT NULL,
	-- When this version of the tier took effect. Historical trades keep the rate that applied on the day.
	"effective_from" DATE NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "fee_tiers" IS 'The fee schedule. Rates live here rather than on the user so that publishing a new schedule is one insert, and every trade snapshots the basis points it actually paid.';
COMMENT ON COLUMN "fee_tiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "fee_tiers"."tier_level" IS 'Ordinal from 0 upwards. Ordering matters, so this is a number and not a name.';
COMMENT ON COLUMN "fee_tiers"."name" IS 'Display name shown on the fee page.';
COMMENT ON COLUMN "fee_tiers"."min_30d_volume_quote" IS 'Rolling thirty-day volume threshold in quote smallest units, normalised to a reference currency. Entering the tier is automatic once volume crosses it.';
COMMENT ON COLUMN "fee_tiers"."maker_fee_bps" IS 'Maker fee in basis points. Integer, because a rate stored as a float turns into a fee that does not match the published table. Can be negative: paying makers to post liquidity is a normal strategy.';
COMMENT ON COLUMN "fee_tiers"."taker_fee_bps" IS 'Taker fee in basis points, always above the maker fee. The spread between the two is what pays for the book being there at all.';
COMMENT ON COLUMN "fee_tiers"."effective_from" IS 'When this version of the tier took effect. Historical trades keep the rate that applied on the day.';

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Order owner.
	"user_id" BIGINT NOT NULL,
	-- Book the order rests on.
	"market_id" BIGINT NOT NULL,
	-- Idempotency key from the client. Market makers resubmit aggressively on timeouts, and without this a network blip becomes a duplicate position.
	"client_order_id" VARCHAR(64) NOT NULL UNIQUE,
	-- buy | sell. A buy locks quote asset, a sell locks base asset, which is why the lock rows name the asset explicitly.
	"side" VARCHAR(4) NOT NULL,
	-- limit | market | stop_limit. Only limit orders rest on the book; a market order is matched and gone.
	"order_type" VARCHAR(12) NOT NULL,
	-- gtc | ioc | fok | gtd. ioc and fok never rest, which means they never hold a lock beyond the matching transaction.
	"time_in_force" VARCHAR(8) NOT NULL DEFAULT 'gtc',
	-- Reject rather than cross the spread. This is how a maker guarantees it will not accidentally pay the taker fee.
	"post_only" BOOLEAN NOT NULL DEFAULT false,
	-- Limit price as an integer count of quote smallest units per one whole base unit. Null for market orders. Integer at the tick scale, so two prices are compared exactly and price-time priority is never a floating-point argument.
	"price_quote" NUMERIC(78,0),
	-- Order size in base smallest units.
	"quantity_base" NUMERIC(78,0) NOT NULL,
	-- Sum of trade quantities so far. Maintained with the fills so cancelling the rest does not need an aggregate.
	"filled_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- Quote smallest units exchanged so far, used to show an average fill price without re-deriving it from trades.
	"quote_spent" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- open | partially_filled | filled | canceled | rejected | expired. partially_filled is a resting state: the remainder is still live on the book.
	"status" VARCHAR(20) NOT NULL DEFAULT 'open',
	-- Tier snapshotted at placement, so a volume recalculation mid-order cannot change the fee of a fill already agreed.
	"fee_tier_id" BIGINT,
	-- Monotonic matching-engine sequence. Price-time priority orders by price then this number, never by created_at: two orders can share a timestamp, and a clock can go backwards.
	"sequence_number" BIGINT NOT NULL,
	-- Acceptance time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the remainder was removed from the book.
	"canceled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'A resting instruction on one book. The open rows for a market, ordered by price and sequence_number, are the order book; the in-memory engine is a cache of exactly this query.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."user_id" IS 'Order owner.';
COMMENT ON COLUMN "orders"."market_id" IS 'Book the order rests on.';
COMMENT ON COLUMN "orders"."client_order_id" IS 'Idempotency key from the client. Market makers resubmit aggressively on timeouts, and without this a network blip becomes a duplicate position.';
COMMENT ON COLUMN "orders"."side" IS 'buy | sell. A buy locks quote asset, a sell locks base asset, which is why the lock rows name the asset explicitly.';
COMMENT ON COLUMN "orders"."order_type" IS 'limit | market | stop_limit. Only limit orders rest on the book; a market order is matched and gone.';
COMMENT ON COLUMN "orders"."time_in_force" IS 'gtc | ioc | fok | gtd. ioc and fok never rest, which means they never hold a lock beyond the matching transaction.';
COMMENT ON COLUMN "orders"."post_only" IS 'Reject rather than cross the spread. This is how a maker guarantees it will not accidentally pay the taker fee.';
COMMENT ON COLUMN "orders"."price_quote" IS 'Limit price as an integer count of quote smallest units per one whole base unit. Null for market orders. Integer at the tick scale, so two prices are compared exactly and price-time priority is never a floating-point argument.';
COMMENT ON COLUMN "orders"."quantity_base" IS 'Order size in base smallest units.';
COMMENT ON COLUMN "orders"."filled_base" IS 'Sum of trade quantities so far. Maintained with the fills so cancelling the rest does not need an aggregate.';
COMMENT ON COLUMN "orders"."quote_spent" IS 'Quote smallest units exchanged so far, used to show an average fill price without re-deriving it from trades.';
COMMENT ON COLUMN "orders"."status" IS 'open | partially_filled | filled | canceled | rejected | expired. partially_filled is a resting state: the remainder is still live on the book.';
COMMENT ON COLUMN "orders"."fee_tier_id" IS 'Tier snapshotted at placement, so a volume recalculation mid-order cannot change the fee of a fill already agreed.';
COMMENT ON COLUMN "orders"."sequence_number" IS 'Monotonic matching-engine sequence. Price-time priority orders by price then this number, never by created_at: two orders can share a timestamp, and a clock can go backwards.';
COMMENT ON COLUMN "orders"."created_at" IS 'Acceptance time.';
COMMENT ON COLUMN "orders"."canceled_at" IS 'When the remainder was removed from the book.';

CREATE INDEX "idx_orders_book"
ON "orders" ("market_id", "status", "price_quote");
CREATE INDEX "idx_orders_user_created"
ON "orders" ("user_id", "created_at");

CREATE TABLE IF NOT EXISTS "trades" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Book the match happened on.
	"market_id" BIGINT NOT NULL,
	-- The order that was already resting. It sets the price, which is the core rule of a continuous auction.
	"maker_order_id" BIGINT NOT NULL,
	-- The order that arrived and crossed the spread. Every trade has exactly one of each, which is why both columns are required.
	"taker_order_id" BIGINT NOT NULL,
	-- Public trade id on the market data feed. Unique so a replayed engine message cannot book a match twice.
	"trade_reference" VARCHAR(64) NOT NULL UNIQUE,
	-- Execution price in quote smallest units per whole base unit. Always the maker price, never the taker limit: the taker gets price improvement, it does not impose one.
	"price_quote" NUMERIC(78,0) NOT NULL,
	-- Matched size in base smallest units, equal to the smaller of the two remaining quantities.
	"quantity_base" NUMERIC(78,0) NOT NULL,
	-- Quote smallest units exchanged, rounded once here. Every fee and balance movement derives from this number rather than recomputing price times quantity.
	"quote_amount" NUMERIC(78,0) NOT NULL,
	-- Fee taken from the maker, in the smallest units of whichever asset the maker received. Negative when the tier pays a rebate.
	"maker_fee_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- Fee taken from the taker, in the smallest units of whichever asset the taker received.
	"taker_fee_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- buy | sell. This is what makes a public tape readable: it tells whether the trade lifted the offer or hit the bid.
	"taker_side" VARCHAR(4) NOT NULL,
	-- Engine sequence, the ordering every downstream consumer replays against. Gaps mean lost messages.
	"sequence_number" BIGINT NOT NULL,
	-- Match time to the microsecond.
	"executed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trades" IS 'One match between two orders. Naming the maker and the taker explicitly rather than storing buyer and seller is what lets fees, rebates and the public tape all be read straight off the row.';
COMMENT ON COLUMN "trades"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trades"."market_id" IS 'Book the match happened on.';
COMMENT ON COLUMN "trades"."maker_order_id" IS 'The order that was already resting. It sets the price, which is the core rule of a continuous auction.';
COMMENT ON COLUMN "trades"."taker_order_id" IS 'The order that arrived and crossed the spread. Every trade has exactly one of each, which is why both columns are required.';
COMMENT ON COLUMN "trades"."trade_reference" IS 'Public trade id on the market data feed. Unique so a replayed engine message cannot book a match twice.';
COMMENT ON COLUMN "trades"."price_quote" IS 'Execution price in quote smallest units per whole base unit. Always the maker price, never the taker limit: the taker gets price improvement, it does not impose one.';
COMMENT ON COLUMN "trades"."quantity_base" IS 'Matched size in base smallest units, equal to the smaller of the two remaining quantities.';
COMMENT ON COLUMN "trades"."quote_amount" IS 'Quote smallest units exchanged, rounded once here. Every fee and balance movement derives from this number rather than recomputing price times quantity.';
COMMENT ON COLUMN "trades"."maker_fee_base" IS 'Fee taken from the maker, in the smallest units of whichever asset the maker received. Negative when the tier pays a rebate.';
COMMENT ON COLUMN "trades"."taker_fee_base" IS 'Fee taken from the taker, in the smallest units of whichever asset the taker received.';
COMMENT ON COLUMN "trades"."taker_side" IS 'buy | sell. This is what makes a public tape readable: it tells whether the trade lifted the offer or hit the bid.';
COMMENT ON COLUMN "trades"."sequence_number" IS 'Engine sequence, the ordering every downstream consumer replays against. Gaps mean lost messages.';
COMMENT ON COLUMN "trades"."executed_at" IS 'Match time to the microsecond.';

CREATE INDEX "idx_trades_market_time"
ON "trades" ("market_id", "executed_at");
CREATE INDEX "idx_trades_maker"
ON "trades" ("maker_order_id");
CREATE INDEX "idx_trades_taker"
ON "trades" ("taker_order_id");

CREATE TABLE IF NOT EXISTS "deposits" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Crediting account, resolved from the deposit address.
	"user_id" BIGINT NOT NULL,
	-- Asset received.
	"asset_id" BIGINT NOT NULL,
	-- Address the funds arrived at. Addresses are assigned per user per asset and never reused, which is the only reliable way to attribute an incoming transfer.
	"deposit_address" VARCHAR(128) NOT NULL,
	-- On-chain transaction hash.
	"transaction_hash" VARCHAR(128) NOT NULL,
	-- Output within the transaction. One transaction can pay several exchange addresses, so the hash alone is not unique.
	"output_index" SMALLINT NOT NULL DEFAULT 0,
	-- Amount received in smallest units, read from the chain rather than from anything a user typed.
	"amount_base" NUMERIC(78,0) NOT NULL,
	-- Confirmations seen so far. Updated as blocks arrive and reset if the chain reorganises.
	"confirmations" SMALLINT NOT NULL DEFAULT 0,
	-- Block containing the transaction. Null while still in the mempool.
	"block_height" BIGINT,
	-- detected | confirming | credited | orphaned | rejected. Credit happens once, at the moment confirmations reach the asset threshold.
	"status" VARCHAR(16) NOT NULL DEFAULT 'detected',
	-- When the node first saw it.
	"detected_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the balance was increased. Null means the funds are visible but unspendable.
	"credited_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "deposits" IS 'An incoming on-chain transfer. The unique key on hash and output index is what makes the chain watcher idempotent: it rescans blocks constantly and must never credit the same output twice.';
COMMENT ON COLUMN "deposits"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "deposits"."user_id" IS 'Crediting account, resolved from the deposit address.';
COMMENT ON COLUMN "deposits"."asset_id" IS 'Asset received.';
COMMENT ON COLUMN "deposits"."deposit_address" IS 'Address the funds arrived at. Addresses are assigned per user per asset and never reused, which is the only reliable way to attribute an incoming transfer.';
COMMENT ON COLUMN "deposits"."transaction_hash" IS 'On-chain transaction hash.';
COMMENT ON COLUMN "deposits"."output_index" IS 'Output within the transaction. One transaction can pay several exchange addresses, so the hash alone is not unique.';
COMMENT ON COLUMN "deposits"."amount_base" IS 'Amount received in smallest units, read from the chain rather than from anything a user typed.';
COMMENT ON COLUMN "deposits"."confirmations" IS 'Confirmations seen so far. Updated as blocks arrive and reset if the chain reorganises.';
COMMENT ON COLUMN "deposits"."block_height" IS 'Block containing the transaction. Null while still in the mempool.';
COMMENT ON COLUMN "deposits"."status" IS 'detected | confirming | credited | orphaned | rejected. Credit happens once, at the moment confirmations reach the asset threshold.';
COMMENT ON COLUMN "deposits"."detected_at" IS 'When the node first saw it.';
COMMENT ON COLUMN "deposits"."credited_at" IS 'When the balance was increased. Null means the funds are visible but unspendable.';

CREATE UNIQUE INDEX "uq_deposits_tx_output"
ON "deposits" ("transaction_hash", "output_index");
CREATE INDEX "idx_deposits_user_asset_status"
ON "deposits" ("user_id", "asset_id", "status");

CREATE TABLE IF NOT EXISTS "withdrawals" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account paying out.
	"user_id" BIGINT NOT NULL,
	-- Asset being sent.
	"asset_id" BIGINT NOT NULL,
	-- Client key on the request. Sending crypto twice is irreversible, so this is the single most important constraint in the table.
	"idempotency_key" VARCHAR(64) NOT NULL UNIQUE,
	-- Where the funds go. Validated against the chain format before the request is accepted, because an invalid address burns the money.
	"destination_address" VARCHAR(128) NOT NULL,
	-- Memo or tag for chains that route by it. Omitting it on those chains loses the funds at the receiving exchange.
	"destination_tag" VARCHAR(64),
	-- Amount requested in smallest units.
	"amount_base" NUMERIC(78,0) NOT NULL,
	-- Fee deducted to pay the miners. Charged on the amount rather than on top, so a user can always withdraw their entire balance.
	"network_fee_base" NUMERIC(78,0) NOT NULL DEFAULT 0,
	-- What actually leaves for the destination. Stored so the user and the chain agree on one number.
	"net_amount_base" NUMERIC(78,0) NOT NULL,
	-- requested | review | approved | broadcast | confirmed | failed | canceled. Funds are locked at requested and only debited at broadcast.
	"status" VARCHAR(20) NOT NULL DEFAULT 'requested',
	-- Hash once broadcast. Null before then, which is exactly the window in which a cancel is still possible.
	"transaction_hash" VARCHAR(128),
	-- When a risk analyst cleared it, for withdrawals that tripped a rule.
	"reviewed_at" TIMESTAMPTZ,
	-- Request time.
	"requested_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the signed transaction hit the network.
	"broadcast_at" TIMESTAMPTZ,
	-- When it reached the required depth.
	"confirmed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "withdrawals" IS 'An outgoing transfer, and the only irreversible operation in the system. The status ladder exists so that funds are locked long before they are debited and debited long before they are unrecoverable.';
COMMENT ON COLUMN "withdrawals"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "withdrawals"."user_id" IS 'Account paying out.';
COMMENT ON COLUMN "withdrawals"."asset_id" IS 'Asset being sent.';
COMMENT ON COLUMN "withdrawals"."idempotency_key" IS 'Client key on the request. Sending crypto twice is irreversible, so this is the single most important constraint in the table.';
COMMENT ON COLUMN "withdrawals"."destination_address" IS 'Where the funds go. Validated against the chain format before the request is accepted, because an invalid address burns the money.';
COMMENT ON COLUMN "withdrawals"."destination_tag" IS 'Memo or tag for chains that route by it. Omitting it on those chains loses the funds at the receiving exchange.';
COMMENT ON COLUMN "withdrawals"."amount_base" IS 'Amount requested in smallest units.';
COMMENT ON COLUMN "withdrawals"."network_fee_base" IS 'Fee deducted to pay the miners. Charged on the amount rather than on top, so a user can always withdraw their entire balance.';
COMMENT ON COLUMN "withdrawals"."net_amount_base" IS 'What actually leaves for the destination. Stored so the user and the chain agree on one number.';
COMMENT ON COLUMN "withdrawals"."status" IS 'requested | review | approved | broadcast | confirmed | failed | canceled. Funds are locked at requested and only debited at broadcast.';
COMMENT ON COLUMN "withdrawals"."transaction_hash" IS 'Hash once broadcast. Null before then, which is exactly the window in which a cancel is still possible.';
COMMENT ON COLUMN "withdrawals"."reviewed_at" IS 'When a risk analyst cleared it, for withdrawals that tripped a rule.';
COMMENT ON COLUMN "withdrawals"."requested_at" IS 'Request time.';
COMMENT ON COLUMN "withdrawals"."broadcast_at" IS 'When the signed transaction hit the network.';
COMMENT ON COLUMN "withdrawals"."confirmed_at" IS 'When it reached the required depth.';

CREATE INDEX "idx_withdrawals_user_status"
ON "withdrawals" ("user_id", "status");

CREATE TABLE IF NOT EXISTS "balance_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account whose balance moves.
	"user_id" BIGINT NOT NULL,
	-- Asset moved.
	"asset_id" BIGINT NOT NULL,
	-- trade | fee | rebate | deposit | withdrawal | lock | unlock | adjustment.
	"entry_type" VARCHAR(20) NOT NULL,
	-- Source trade, when the movement came from a match. A single trade writes four entries: base and quote for each side.
	"trade_id" BIGINT,
	-- Source deposit.
	"deposit_id" BIGINT,
	-- Source withdrawal.
	"withdrawal_id" BIGINT,
	-- Signed amount in smallest units. Negative leaves the account. The sum of this column per user and asset must equal available plus locked, which is the reconciliation that runs nightly.
	"amount_base" NUMERIC(78,0) NOT NULL,
	-- Balance after the entry, written in the same transaction so a statement never needs a window function over the whole history.
	"balance_after_base" NUMERIC(78,0) NOT NULL,
	-- Write time. The table is append-only: corrections are new entries with entry_type adjustment.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "balance_entries" IS 'The append-only journal that wallet_balances summarises. Without it a wrong balance has no explanation; with it, every satoshi in the account has a row saying where it came from.';
COMMENT ON COLUMN "balance_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "balance_entries"."user_id" IS 'Account whose balance moves.';
COMMENT ON COLUMN "balance_entries"."asset_id" IS 'Asset moved.';
COMMENT ON COLUMN "balance_entries"."entry_type" IS 'trade | fee | rebate | deposit | withdrawal | lock | unlock | adjustment.';
COMMENT ON COLUMN "balance_entries"."trade_id" IS 'Source trade, when the movement came from a match. A single trade writes four entries: base and quote for each side.';
COMMENT ON COLUMN "balance_entries"."deposit_id" IS 'Source deposit.';
COMMENT ON COLUMN "balance_entries"."withdrawal_id" IS 'Source withdrawal.';
COMMENT ON COLUMN "balance_entries"."amount_base" IS 'Signed amount in smallest units. Negative leaves the account. The sum of this column per user and asset must equal available plus locked, which is the reconciliation that runs nightly.';
COMMENT ON COLUMN "balance_entries"."balance_after_base" IS 'Balance after the entry, written in the same transaction so a statement never needs a window function over the whole history.';
COMMENT ON COLUMN "balance_entries"."created_at" IS 'Write time. The table is append-only: corrections are new entries with entry_type adjustment.';

CREATE INDEX "idx_entries_user_asset_created"
ON "balance_entries" ("user_id", "asset_id", "created_at");

CREATE TABLE IF NOT EXISTS "order_book_snapshots" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Book captured.
	"market_id" BIGINT NOT NULL,
	-- Engine sequence at capture. A client replays incremental updates from exactly this number, so a snapshot without it is useless.
	"sequence_number" BIGINT NOT NULL,
	-- Array of price and aggregate quantity pairs, best first. Aggregated by level rather than listing individual orders, because that is what a chart consumes.
	"bids" JSONB NOT NULL,
	-- Same shape for the sell side.
	"asks" JSONB NOT NULL,
	-- How many price levels were captured. Kept because analysis over a mix of depths needs to know what was truncated.
	"depth_levels" SMALLINT NOT NULL DEFAULT 50,
	-- Midpoint of best bid and best ask at capture, denormalised so a time series query does not have to open the JSON.
	"mid_price_quote" NUMERIC(78,0),
	-- Capture time.
	"captured_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "order_book_snapshots" IS 'Periodic photographs of the book, for backtesting and for bootstrapping a streaming client. Deliberately denormalised into JSON: this data is written once, read sequentially, and never joined.';
COMMENT ON COLUMN "order_book_snapshots"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "order_book_snapshots"."market_id" IS 'Book captured.';
COMMENT ON COLUMN "order_book_snapshots"."sequence_number" IS 'Engine sequence at capture. A client replays incremental updates from exactly this number, so a snapshot without it is useless.';
COMMENT ON COLUMN "order_book_snapshots"."bids" IS 'Array of price and aggregate quantity pairs, best first. Aggregated by level rather than listing individual orders, because that is what a chart consumes.';
COMMENT ON COLUMN "order_book_snapshots"."asks" IS 'Same shape for the sell side.';
COMMENT ON COLUMN "order_book_snapshots"."depth_levels" IS 'How many price levels were captured. Kept because analysis over a mix of depths needs to know what was truncated.';
COMMENT ON COLUMN "order_book_snapshots"."mid_price_quote" IS 'Midpoint of best bid and best ask at capture, denormalised so a time series query does not have to open the JSON.';
COMMENT ON COLUMN "order_book_snapshots"."captured_at" IS 'Capture time.';

CREATE UNIQUE INDEX "uq_snapshots_market_sequence"
ON "order_book_snapshots" ("market_id", "sequence_number");
CREATE INDEX "idx_snapshots_market_time"
ON "order_book_snapshots" ("market_id", "captured_at");

